import{_ as l,l as r,o as a,c,v as t,p as o,x as i,d as n,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"tickless","description":"","frontmatter":{"title":"tickless","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tickless-nohz.md","filePath":"cs/tickless-nohz.md","lastUpdated":1789023840000}'),p={name:"cs/tickless-nohz.md"};function k(_,e,u,f,m,E){const s=r("Mermaid");return a(),c("div",null,[e[1]||(e[1]=t('<h1 id="tickless" tabindex="-1">tickless <a class="header-anchor" href="#tickless" aria-label="Permalink to &quot;tickless&quot;">​</a></h1><div class="epigraph"><p>NO_HZ 在核空闲（或甚至有任务但动态）时关掉周期性调度 tick，用 hrtimer 在真正需要时再响，让 C-state 能睡稳。</p><footer>—— 据 Linux timers/NO_HZ 文档；Corbet 对 tickless 的 LWN 整理</footer></div><p><a href="/cs/cpuidle-cstate">cpuidle</a> 被周期性 tick 吵醒就进不了深 C。<a href="/cs/eevdf">EEVDF</a> 仍要记账。缺口是 <strong>tickless</strong>：idle 与 full dynticks 的差别。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统 HZ 次/秒中断，空闲也响。<code>NO_HZ_IDLE</code>：空闲停 tick。<code>NO_HZ_FULL</code>：隔离核上单任务也可停，给 HPC/RT。缺口：时间会计靠进入/退出补；POSIX CPU 时钟变粗；RCU 回调要有核处理。本课不把所有 nohz 限制列出。</p><p><span class="marginnote">隔离核仍要偶尔处理 IPIs。对象是时钟中断策略，不是用户 crontab。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>idle 入口：取消 tick，设下一个需要的 hrtimer。busy nohz full：把该 CPU 移出常规 tick 掩码。对照 <a href="/cs/napi">NAPI</a>：包 IRQ 仍在。对照 cyclictest：tick 本身是抖动源。对照 <a href="/cs/kpti-os">KPTI</a>：无关页表。</p>',8)),(a(),o(h,null,{default:i(()=>[d(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IDLE%5B%22%E8%BF%9B%E5%85%A5%E7%A9%BA%E9%97%B2%22%5D%20--%3E%20STOP%5B%22%E5%81%9C%E5%91%A8%E6%9C%9F%E6%80%A7%20tick%22%5D%0A%20%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E4%BB%B6%E5%88%B0%E6%9C%9F%E4%BA%8B%22%5D%20--%3E%20HRT%5B%22hrtimer%22%5D%0A%20%20HRT%20--%3E%20WAKE%5B%22%E5%86%8D%E5%93%8D%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>tickless 把「OS 心跳」从固定频率变成事件驱动，服务功耗与隔离核确定性。记账与 RCU 是税。不要写成取消调度。与 <a href="/cs/fairness-metrics">fairness</a>：无 tick 时份额靠其它更新点。</p><p>full nohz 配置错误会导致时间不准或 RCU stall。</p><p>实现上：full nohz 要求该 CPU 上几乎只有一个任务，RCU 回调要有人代跑。POSIX CPU 时钟会计变粗。隔离后仍可能被 IPI 和定时器打醒。 读法上只引用<a href="/cs/cpuidle-cstate">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>tickless</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 xen 偷 tick 的全部。不保证虚拟化 guest 的 nohz。调度课序收口于定时器实现：timer wheel。</p><p>版本字段会变，课序钉的是机制对象「tickless」，不是某一主线内核的结构体名。 后课默认：空闲可停 HZ tick。内核如何组织大量定时器，下一课定时器轮。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NO_HZ 停周期性 tick，改用 hrtimer。</li><li>full nohz 服务隔离核，约束多。</li><li>定时器轮是下一课。</li><li>出处：Linux NO_HZ；LWN tickless。</li></ul>',11))])}const B=l(p,[["render",k]]);export{T as __pageData,B as default};
